import Foundation

public struct SchoolResource: Hashable, Sendable {
    public let title: String
    public let url: URL
}
public struct SchoolRecord: Identifiable, Hashable, Sendable {
    public let id: String
    public let name: String
    public let organization: String?
    public let county: String?
    public let municipality: String
    public let type: String
    public let grades: String
    public let website: URL?
    public let sourceURL: URL
    public let verifiedOn: String
    public let aliases: [String]
    public let resources: [SchoolResource]
    public func matches(_ query: String) -> Bool {
        let q = query.trimmingCharacters(in:.whitespacesAndNewlines)
        return q.isEmpty || ([name, municipality] + aliases).contains { $0.localizedCaseInsensitiveContains(q) }
    }
}
